INSERT INTO public.exams (slug,title,source,year) VALUES ('espcex-2026-dia-1','EsPCEx 2026 · 1º dia','espcex','2026')
ON CONFLICT (slug) DO UPDATE SET title=excluded.title,source=excluded.source,year=excluded.year;
WITH data AS (SELECT '{"slug": "espcex-2026-dia-1", "source": "espcex", "year": "2026", "title": "EsPCEx 2026 · 1º dia", "questions": [{"number": 1, "subject": "Língua Portuguesa", "text": "No chamado discurso indireto livre, a voz da personagem\nmescla-se intimamente à voz do narrador, a exemplo do que\nocorre em:", "support": "Para responder às questões de 01 a 04, leia um trecho do conto “A pátria”, do escritor Olavo Bilac (1865-1918), o Patrono do\nServiço Militar. Não por acaso, a sua data de nascimento, 16\nde dezembro, foi consagrada como Dia do Reservista.\n1 O pai, velho soldado que a vida das guerras alquebrara¹,\ngostava de lembrar, à noite, quando toda a família se reunia na\nsala de jantar em roda da grande mesa antiga, os episódios\ndas campanhas que vira.\nA mulher não ouvia com prazer aquelas histórias de cargas de cavalaria, de emboscadas, de assaltos, tão cheias de\nsangue e de horror. Quando o velho recordava aquele tempo,\nela revivia a angústia dos dias passados na solidão, sem notícias do marido que lá andava pelo Paraguai. Lembrava-se da\nansiedade e do medo com que esperava o correio, naquelas\namaldiçoadas tardes de desespero. Quando o carteiro lhe entregava um envelope fechado, — quantos minutos ficava ela\na mirar e a revolver nas mãos aquele pedaço de papel que\nvinha do querido ausente, e que tinha recebido os seus beijos\ne as suas lágrimas de saudade!\nPor fim abria a carta. A princípio não podia ler. Tremia-lhe\nnos dedos o papel. Tinha de repousar um pouco: e, quando\nconseguia terminar a leitura, ficava abatida e sem consolo\ndiante daquelas notícias que não variavam nunca. Era sempre\na mesma coisa: não se sabia quando acabaria a guerra; mas\nDeus velava por ele; era preciso assegurar, conquistando um\nbom posto, um futuro feliz para os filhos; além disso a Pátria\nestava acima de tudo...\nEla amarrotava a carta... A Pátria! que era a Pátria, para\nvaler mais do que ela, mais do que aquelas duas crianças, pobres inocentes que talvez a essa mesma hora já estivessem\nsem pai? Ia então contemplar os filhos, e ali ficava chorando,\nhoras inteiras...\n5 Quando o pai voltou da guerra, vinha major. Fora ferido.\nPerdera uma perna. A mulher abençoou essa desgraça. Ao menos, assim mutilado, ficava ele posto à margem, dispensado\nde voltar à mesma existência de perigos e canseiras. Podiam\nviver modestamente com seu soldo². Qualquer outro trabalho\nleve de que se pudesse encarregar dar-lhe-ia o suficiente para\neducar os filhos. Agora, porém, quando o velho major, durante\nos serões domésticos, começava a contar os seus episódios de\ncampanha, a mulher estremecia.\nNo entusiasmo da narração, o velho transfigurava-se. O\nseu braço, estendido no ar, indicava os golpes de espada. A\nsua voz imitava, ora o ruído contínuo e seco da fuzilaria, ora o\nestrondo rouco dos canhoneios. Diante dele, Carlos, também\ntransfigurado, bebia as suas palavras, com inveja, respirando\na custo, agitando-se na cadeira. E a mãe quase rebentava\nem soluços, vendo a alegria do filho. Era aquele, há muito\ntempo, o seu maior receio... Pobre mãe! Desde o tempo em\nque apenas devia pensar em bonecos, o menino manifestava\numa grande predileção pelas coisas da vida militar.\nFicava horas inteiras contemplando as fardas do pai: e, à\nnoite, deixando de estudar, fechando sobre a mesa as suas\ngramáticas e os seus dicionários, era ele o primeiro a pedir\nao velho mais uma daquelas narrações que o embriagavam.\nQuando foi preciso escolher uma carreira, Carlos, sem hesitação, declarou que queria ir para a Escola Militar. O velho\nexultou³. A mulher, resignada, não teve protesto.\n(Olavo Bilac & Coelho Neto. Contos pátrios, 1906. Adaptado.)\n1 alquebrar: dobrar ou sofrer curvatura da espinha por doença, fraqueza ou\nvelhice.\n2 soldo: salário de militares.\n3", "support_image": null, "options": ["“A Pátria! que era a Pátria, para valer mais do que ela, mais do que aquelas duas crianças, pobres inocentes que talvez a essa mesma hora já estivessem sem pai?” (4o parágrafo)", "“O pai, velho soldado que a vida das guerras alquebrara, gostava de lembrar, à noite, quando toda a família se reunia na sala de jantar em roda da grande mesa antiga, os episódios das campanhas que vira.” (1o parágrafo)", "“Agora, porém, quando o velho major, durante os serões domésticos, começava a contar os seus episódios de campanha, a mulher estremecia.” (5o parágrafo)", "“O seu braço, estendido no ar, indicava os golpes de espada. A sua voz imitava, ora o ruído contínuo e seco da fuzilaria, ora o estrondo rouco dos canhoneios.” (6o parágrafo)", "“Quando foi preciso escolher uma carreira, Carlos, sem hesitação, declarou que queria ir para a Escola Militar. O velho exultou.” (7o parágrafo)"], "answer": "A", "explanation": null, "page": 3}, {"number": 2, "subject": "Língua Portuguesa", "text": "● “Lembrava-se da ansiedade e do medo com que esperava o correio, naquelas amaldiçoadas tardes de desespero.”\n(2o parágrafo)\n● “Diante dele, Carlos, também transfigurado, bebia as\nsuas palavras, com inveja, respirando a custo, agitando-se\nna cadeira.” (6o parágrafo)\n● “à noite, deixando de estudar, fechando sobre a mesa\nas suas gramáticas e os seus dicionários, era ele o primeiro\na pedir ao velho mais uma daquelas narrações que o embriagavam.” (7o parágrafo)\nOs verbos sublinhados estão empregados, respectivamente,\nem sentido", "support": "Para responder às questões de 01 a 04, leia um trecho do conto “A pátria”, do escritor Olavo Bilac (1865-1918), o Patrono do\nServiço Militar. Não por acaso, a sua data de nascimento, 16\nde dezembro, foi consagrada como Dia do Reservista.\n1 O pai, velho soldado que a vida das guerras alquebrara¹,\ngostava de lembrar, à noite, quando toda a família se reunia na\nsala de jantar em roda da grande mesa antiga, os episódios\ndas campanhas que vira.\nA mulher não ouvia com prazer aquelas histórias de cargas de cavalaria, de emboscadas, de assaltos, tão cheias de\nsangue e de horror. Quando o velho recordava aquele tempo,\nela revivia a angústia dos dias passados na solidão, sem notícias do marido que lá andava pelo Paraguai. Lembrava-se da\nansiedade e do medo com que esperava o correio, naquelas\namaldiçoadas tardes de desespero. Quando o carteiro lhe entregava um envelope fechado, — quantos minutos ficava ela\na mirar e a revolver nas mãos aquele pedaço de papel que\nvinha do querido ausente, e que tinha recebido os seus beijos\ne as suas lágrimas de saudade!\nPor fim abria a carta. A princípio não podia ler. Tremia-lhe\nnos dedos o papel. Tinha de repousar um pouco: e, quando\nconseguia terminar a leitura, ficava abatida e sem consolo\ndiante daquelas notícias que não variavam nunca. Era sempre\na mesma coisa: não se sabia quando acabaria a guerra; mas\nDeus velava por ele; era preciso assegurar, conquistando um\nbom posto, um futuro feliz para os filhos; além disso a Pátria\nestava acima de tudo...\nEla amarrotava a carta... A Pátria! que era a Pátria, para\nvaler mais do que ela, mais do que aquelas duas crianças, pobres inocentes que talvez a essa mesma hora já estivessem\nsem pai? Ia então contemplar os filhos, e ali ficava chorando,\nhoras inteiras...\n5 Quando o pai voltou da guerra, vinha major. Fora ferido.\nPerdera uma perna. A mulher abençoou essa desgraça. Ao menos, assim mutilado, ficava ele posto à margem, dispensado\nde voltar à mesma existência de perigos e canseiras. Podiam\nviver modestamente com seu soldo². Qualquer outro trabalho\nleve de que se pudesse encarregar dar-lhe-ia o suficiente para\neducar os filhos. Agora, porém, quando o velho major, durante\nos serões domésticos, começava a contar os seus episódios de\ncampanha, a mulher estremecia.\nNo entusiasmo da narração, o velho transfigurava-se. O\nseu braço, estendido no ar, indicava os golpes de espada. A\nsua voz imitava, ora o ruído contínuo e seco da fuzilaria, ora o\nestrondo rouco dos canhoneios. Diante dele, Carlos, também\ntransfigurado, bebia as suas palavras, com inveja, respirando\na custo, agitando-se na cadeira. E a mãe quase rebentava\nem soluços, vendo a alegria do filho. Era aquele, há muito\ntempo, o seu maior receio... Pobre mãe! Desde o tempo em\nque apenas devia pensar em bonecos, o menino manifestava\numa grande predileção pelas coisas da vida militar.\nFicava horas inteiras contemplando as fardas do pai: e, à\nnoite, deixando de estudar, fechando sobre a mesa as suas\ngramáticas e os seus dicionários, era ele o primeiro a pedir\nao velho mais uma daquelas narrações que o embriagavam.\nQuando foi preciso escolher uma carreira, Carlos, sem hesitação, declarou que queria ir para a Escola Militar. O velho\nexultou³. A mulher, resignada, não teve protesto.\n(Olavo Bilac & Coelho Neto. Contos pátrios, 1906. Adaptado.)\n1 alquebrar: dobrar ou sofrer curvatura da espinha por doença, fraqueza ou\nvelhice.\n2 soldo: salário de militares.\n3", "support_image": null, "options": ["figurado, literal e figurado.", "literal, figurado e figurado.", "literal, literal e figurado.", "figurado, figurado e literal.", "literal, figurado e literal."], "answer": "B", "explanation": null, "page": 3}, {"number": 3, "subject": "Língua Portuguesa", "text": "Os termos sublinhados no segundo e no sexto parágrafos do\ntexto referem-se, respectivamente, a", "support": "Para responder às questões de 01 a 04, leia um trecho do conto “A pátria”, do escritor Olavo Bilac (1865-1918), o Patrono do\nServiço Militar. Não por acaso, a sua data de nascimento, 16\nde dezembro, foi consagrada como Dia do Reservista.\n1 O pai, velho soldado que a vida das guerras alquebrara¹,\ngostava de lembrar, à noite, quando toda a família se reunia na\nsala de jantar em roda da grande mesa antiga, os episódios\ndas campanhas que vira.\nA mulher não ouvia com prazer aquelas histórias de cargas de cavalaria, de emboscadas, de assaltos, tão cheias de\nsangue e de horror. Quando o velho recordava aquele tempo,\nela revivia a angústia dos dias passados na solidão, sem notícias do marido que lá andava pelo Paraguai. Lembrava-se da\nansiedade e do medo com que esperava o correio, naquelas\namaldiçoadas tardes de desespero. Quando o carteiro lhe entregava um envelope fechado, — quantos minutos ficava ela\na mirar e a revolver nas mãos aquele pedaço de papel que\nvinha do querido ausente, e que tinha recebido os seus beijos\ne as suas lágrimas de saudade!\nPor fim abria a carta. A princípio não podia ler. Tremia-lhe\nnos dedos o papel. Tinha de repousar um pouco: e, quando\nconseguia terminar a leitura, ficava abatida e sem consolo\ndiante daquelas notícias que não variavam nunca. Era sempre\na mesma coisa: não se sabia quando acabaria a guerra; mas\nDeus velava por ele; era preciso assegurar, conquistando um\nbom posto, um futuro feliz para os filhos; além disso a Pátria\nestava acima de tudo...\nEla amarrotava a carta... A Pátria! que era a Pátria, para\nvaler mais do que ela, mais do que aquelas duas crianças, pobres inocentes que talvez a essa mesma hora já estivessem\nsem pai? Ia então contemplar os filhos, e ali ficava chorando,\nhoras inteiras...\n5 Quando o pai voltou da guerra, vinha major. Fora ferido.\nPerdera uma perna. A mulher abençoou essa desgraça. Ao menos, assim mutilado, ficava ele posto à margem, dispensado\nde voltar à mesma existência de perigos e canseiras. Podiam\nviver modestamente com seu soldo². Qualquer outro trabalho\nleve de que se pudesse encarregar dar-lhe-ia o suficiente para\neducar os filhos. Agora, porém, quando o velho major, durante\nos serões domésticos, começava a contar os seus episódios de\ncampanha, a mulher estremecia.\nNo entusiasmo da narração, o velho transfigurava-se. O\nseu braço, estendido no ar, indicava os golpes de espada. A\nsua voz imitava, ora o ruído contínuo e seco da fuzilaria, ora o\nestrondo rouco dos canhoneios. Diante dele, Carlos, também\ntransfigurado, bebia as suas palavras, com inveja, respirando\na custo, agitando-se na cadeira. E a mãe quase rebentava\nem soluços, vendo a alegria do filho. Era aquele, há muito\ntempo, o seu maior receio... Pobre mãe! Desde o tempo em\nque apenas devia pensar em bonecos, o menino manifestava\numa grande predileção pelas coisas da vida militar.\nFicava horas inteiras contemplando as fardas do pai: e, à\nnoite, deixando de estudar, fechando sobre a mesa as suas\ngramáticas e os seus dicionários, era ele o primeiro a pedir\nao velho mais uma daquelas narrações que o embriagavam.\nQuando foi preciso escolher uma carreira, Carlos, sem hesitação, declarou que queria ir para a Escola Militar. O velho\nexultou³. A mulher, resignada, não teve protesto.\n(Olavo Bilac & Coelho Neto. Contos pátrios, 1906. Adaptado.)\n1 alquebrar: dobrar ou sofrer curvatura da espinha por doença, fraqueza ou\nvelhice.\n2 soldo: salário de militares.\n3", "support_image": null, "options": ["“pedaço de papel” e “menino”.", "“querido ausente” (o marido) e “menino”.", "“ela” (a mulher) e “tempo”.", "“ela” (a mulher) e “menino”.", "“pedaço de papel” e “tempo”."], "answer": "E", "explanation": null, "page": 4}, {"number": 4, "subject": "Língua Portuguesa", "text": "Pode ser atribuído valor de posse ao pronome sublinhado no\nseguinte trecho:", "support": "Para responder às questões de 01 a 04, leia um trecho do conto “A pátria”, do escritor Olavo Bilac (1865-1918), o Patrono do\nServiço Militar. Não por acaso, a sua data de nascimento, 16\nde dezembro, foi consagrada como Dia do Reservista.\n1 O pai, velho soldado que a vida das guerras alquebrara¹,\ngostava de lembrar, à noite, quando toda a família se reunia na\nsala de jantar em roda da grande mesa antiga, os episódios\ndas campanhas que vira.\nA mulher não ouvia com prazer aquelas histórias de cargas de cavalaria, de emboscadas, de assaltos, tão cheias de\nsangue e de horror. Quando o velho recordava aquele tempo,\nela revivia a angústia dos dias passados na solidão, sem notícias do marido que lá andava pelo Paraguai. Lembrava-se da\nansiedade e do medo com que esperava o correio, naquelas\namaldiçoadas tardes de desespero. Quando o carteiro lhe entregava um envelope fechado, — quantos minutos ficava ela\na mirar e a revolver nas mãos aquele pedaço de papel que\nvinha do querido ausente, e que tinha recebido os seus beijos\ne as suas lágrimas de saudade!\nPor fim abria a carta. A princípio não podia ler. Tremia-lhe\nnos dedos o papel. Tinha de repousar um pouco: e, quando\nconseguia terminar a leitura, ficava abatida e sem consolo\ndiante daquelas notícias que não variavam nunca. Era sempre\na mesma coisa: não se sabia quando acabaria a guerra; mas\nDeus velava por ele; era preciso assegurar, conquistando um\nbom posto, um futuro feliz para os filhos; além disso a Pátria\nestava acima de tudo...\nEla amarrotava a carta... A Pátria! que era a Pátria, para\nvaler mais do que ela, mais do que aquelas duas crianças, pobres inocentes que talvez a essa mesma hora já estivessem\nsem pai? Ia então contemplar os filhos, e ali ficava chorando,\nhoras inteiras...\n5 Quando o pai voltou da guerra, vinha major. Fora ferido.\nPerdera uma perna. A mulher abençoou essa desgraça. Ao menos, assim mutilado, ficava ele posto à margem, dispensado\nde voltar à mesma existência de perigos e canseiras. Podiam\nviver modestamente com seu soldo². Qualquer outro trabalho\nleve de que se pudesse encarregar dar-lhe-ia o suficiente para\neducar os filhos. Agora, porém, quando o velho major, durante\nos serões domésticos, começava a contar os seus episódios de\ncampanha, a mulher estremecia.\nNo entusiasmo da narração, o velho transfigurava-se. O\nseu braço, estendido no ar, indicava os golpes de espada. A\nsua voz imitava, ora o ruído contínuo e seco da fuzilaria, ora o\nestrondo rouco dos canhoneios. Diante dele, Carlos, também\ntransfigurado, bebia as suas palavras, com inveja, respirando\na custo, agitando-se na cadeira. E a mãe quase rebentava\nem soluços, vendo a alegria do filho. Era aquele, há muito\ntempo, o seu maior receio... Pobre mãe! Desde o tempo em\nque apenas devia pensar em bonecos, o menino manifestava\numa grande predileção pelas coisas da vida militar.\nFicava horas inteiras contemplando as fardas do pai: e, à\nnoite, deixando de estudar, fechando sobre a mesa as suas\ngramáticas e os seus dicionários, era ele o primeiro a pedir\nao velho mais uma daquelas narrações que o embriagavam.\nQuando foi preciso escolher uma carreira, Carlos, sem hesitação, declarou que queria ir para a Escola Militar. O velho\nexultou³. A mulher, resignada, não teve protesto.\n(Olavo Bilac & Coelho Neto. Contos pátrios, 1906. Adaptado.)\n1 alquebrar: dobrar ou sofrer curvatura da espinha por doença, fraqueza ou\nvelhice.\n2 soldo: salário de militares.\n3", "support_image": null, "options": ["“Qualquer outro trabalho leve de que se pudesse encarregar dar-lhe-ia o suficiente” (5o parágrafo).", "“No entusiasmo da narração, o velho transfigurava-se” (6o parágrafo).", "“Tremia-lhe nos dedos o papel” (3o parágrafo).", "“Lembrava-se da ansiedade e do medo” (2o parágrafo).", "“Quando o carteiro lhe entregava um envelope fechado” (2o parágrafo)."], "answer": "C", "explanation": null, "page": 4}, {"number": 5, "subject": "Língua Portuguesa", "text": "Examine a tirinha do cartunista Fernando Gonsales, publicada\npelo perfil @niquel.nausea no Instagram em 27.03.2026.\nNa construção de seu sentido, a tirinha mobiliza fundamentalmente os seguintes recursos expressivos:", "support": null, "support_image": "/militares-2026/espcex-2026-dia-1-q5-figura-1.png", "options": ["hipérbole e pleonasmo.", "intertextualidade e eufemismo.", "eufemismo e pleonasmo.", "intertextualidade e polissemia.", "hipérbole e polissemia."], "answer": "D", "explanation": null, "page": 4}, {"number": 6, "subject": "Língua Portuguesa", "text": "Motivado pelas teorias científicas e filosóficas da segunda\nmetade do século XIX, esse movimento literário se empenhava\nem retratar o homem e a sociedade em conjunto. Não bastava\nmostrar a face sonhadora e idealizada da vida, como haviam\nfeito, em larga medida, os escritores da primeira metade do século XIX; era preciso mostrar a face do cotidiano massacrante,\ndo casamento por interesse, do amor adúltero, da falsidade e\ndo egoísmo, da impotência do ser humano comum diante dos\npoderosos.\n(William Roberto Cereja e Thereza Cochar Magalhães. Literatura brasileira:\nem diálogo com outras literaturas e outras linguagens, 2013. Adaptado.)\nO movimento literário a que o excerto se refere é o", "support": null, "support_image": null, "options": ["Romantismo.", "Realismo.", "Arcadismo.", "Parnasianismo.", "Simbolismo. a responder às questões de 07 a 14, leia o soneto “LXXI” poeta Cláudio Manuel da Costa (1729-1789). Eu cantei, não o nego, eu algum dia Cantei do injusto Amor o vencimento, Sem saber que o veneno mais violento Nas doces expressões falso encobria. Que Amor era benigno, eu persuadia A qualquer coração de Amor isento; Inda agora de Amor cantara atento, Se lhe não conhecera a aleivosia¹. Ninguém de Amor se fie: agora canto Somente os seus enganos, porque sinto Que me tem destinado estrago tanto. De seu favor hoje as quimeras² pinto: Amor de uma alma é pesaroso³ encanto; Amor de um coração é labirinto. (Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.) ivosia: engano, traição. mera: ilusão. saroso: em que há pesar, ou seja, tristeza, desolação."], "answer": "B", "explanation": null, "page": 5}, {"number": 7, "subject": "Língua Portuguesa", "text": "Em relação ao amor, o eu lírico expressa, sobretudo, uma\nvisão", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["ingênua.", "desiludida.", "idealizada.", "sensual.", "platônica."], "answer": "B", "explanation": null, "page": 5}, {"number": 8, "subject": "Língua Portuguesa", "text": "O emprego dos verbos “canto” (3a estrofe) e “pinto” (4a estrofe)\nexplicita o teor", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["místico-religioso do soneto.", "histórico-social do soneto.", "irônico do soneto.", "nostálgico do soneto.", "metalinguístico do soneto."], "answer": "E", "explanation": null, "page": 5}, {"number": 9, "subject": "Língua Portuguesa", "text": "Opõem-se semanticamente os termos que compõem a seguinte expressão:", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["“pesaroso encanto” (4a estrofe).", "“veneno [...] violento” (1a estrofe).", "“injusto Amor” (1a estrofe).", "“doces expressões” (1a estrofe).", "“coração [...] isento” (2a estrofe)."], "answer": "A", "explanation": null, "page": 5}, {"number": 10, "subject": "Língua Portuguesa", "text": "Um traço estilístico que afasta esse soneto do Neoclassicismo,\naproximando-o da estética romântica, é", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["a predileção pela temática onírica.", "o culto da impessoalidade.", "a ênfase na expressão subjetiva.", "a referência a entidades mitológicas.", "o elogio da vida bucólica."], "answer": "C", "explanation": null, "page": 5}, {"number": 11, "subject": "Língua Portuguesa", "text": "Retoma uma informação mencionada anteriormente no soneto\no termo sublinhado no seguinte verso:", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["“A qualquer coração de Amor isento;” (2a estrofe)", "“Cantei do injusto Amor o vencimento,” (1a estrofe)", "“Se lhe não conhecera a aleivosia.” (2a estrofe)", "“Eu cantei, não o nego, eu algum dia” (1a estrofe)", "“Sem saber que o veneno mais violento” (1a estrofe)"], "answer": "D", "explanation": null, "page": 5}, {"number": 12, "subject": "Língua Portuguesa", "text": "Por razões estilísticas, Cláudio Manuel da Costa recorre a\nvárias inversões sintáticas. Um exemplo são os versos “Que\nAmor era benigno, eu persuadia / A qualquer coração de\nAmor isento;” (2a estrofe). Em ordem direta, esses versos\nassumem a seguinte redação:", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["A qualquer coração isento de Amor eu persuadia que Amor era benigno.", "Eu persuadia que Amor era benigno a qualquer coração isento de Amor.", "Amor persuadia a qualquer coração isento de Amor que eu era benigno.", "Eu persuadia a qualquer coração de Amor isento que Amor era benigno.", "Amor persuadia que eu era benigno a qualquer coração de Amor isento."], "answer": "B", "explanation": null, "page": 6}, {"number": 13, "subject": "Língua Portuguesa", "text": "Na linguagem poética, visando obter maior expressividade,\npode-se empregar um tempo verbal em lugar de outro. É o\nque ocorre nos seguintes versos:", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["“Eu cantei, não o nego, eu algum dia / Cantei do injusto Amor o vencimento,” (1a estrofe)", "“Amor de uma alma é pesaroso encanto; / Amor de um coração é labirinto.” (4a estrofe)", "“Inda agora de Amor cantara atento, / Se lhe não conhecera a aleivosia.” (2a estrofe)", "“Sem saber que o veneno mais violento / Nas doces expressões falso encobria.” (1a estrofe)", "“Que Amor era benigno, eu persuadia / A qualquer coração de Amor isento;” (2a estrofe)"], "answer": "C", "explanation": null, "page": 6}, {"number": 14, "subject": "Língua Portuguesa", "text": "Embora predominem no soneto as chamadas rimas ricas,\no poeta recorre também a uma rima pobre (ou seja, aquela\nentre palavras de mesma classe gramatical). Trata-se da\nrima entre", "support": "Para responder às questões de 07 a 14, leia o soneto “LXXI”\ndo poeta Cláudio Manuel da Costa (1729-1789).\nEu cantei, não o nego, eu algum dia\nCantei do injusto Amor o vencimento,\nSem saber que o veneno mais violento\nNas doces expressões falso encobria.\nQue Amor era benigno, eu persuadia\nA qualquer coração de Amor isento;\nInda agora de Amor cantara atento,\nSe lhe não conhecera a aleivosia¹.\nNinguém de Amor se fie: agora canto\nSomente os seus enganos, porque sinto\nQue me tem destinado estrago tanto.\nDe seu favor hoje as quimeras² pinto:\nAmor de uma alma é pesaroso³ encanto;\nAmor de um coração é labirinto.\n(Domício Proença Filho (org.). A poesia dos inconfidentes, 1996.)\n1 aleivosia: engano, traição.\n2 quimera: ilusão.\n3 pesaroso: em que há pesar, ou seja, tristeza, desolação.", "support_image": null, "options": ["“tanto” (3a estrofe) e “encanto” (4a estrofe).", "“sinto” (3a estrofe) e “pinto” (4a estrofe).", "“dia” (1a estrofe) e “encobria” (1a estrofe).", "“persuadia” (2a estrofe) e “aleivosia” (2a estrofe).", "“vencimento” (1a estrofe) e “violento” (1a estrofe)."], "answer": "B", "explanation": null, "page": 6}, {"number": 15, "subject": "Língua Portuguesa", "text": "Examine o cartum de Rafael Corrêa.\n(Rafael Corrêa. Até aqui tudo bem, 2018.)\nPara obter seu efeito de humor, o cartum explora o fenômeno\nlinguístico denominado", "support": null, "support_image": "/militares-2026/espcex-2026-dia-1-q15-figura-1.png", "options": ["homografia: duas palavras idênticas na grafia que têm sonoridades e significados diferentes.", "sinonímia: duas palavras que têm significados muito próximos.", "paronímia: duas palavras parecidas na grafia e na sonoridade que têm significados diferentes.", "antonímia: duas palavras que têm significados opostos.", "homofonia: duas palavras idênticas na sonoridade que têm grafias e significados diferentes."], "answer": "E", "explanation": null, "page": 6}, {"number": 16, "subject": "Língua Portuguesa", "text": "O texto transcrito é um artigo de divulgação científica. Uma\ncaracterística textual que o afasta de um artigo científico é o\nemprego de", "support": "Leia o texto “Zonas mortas nos oceanos”, do biólogo brasileiro\nFernando Reinach, para responder às questões de 16 a 20.\nÉ fácil sensibilizar o mundo para o desmatamento da\nfloresta amazônica, fotos de troncos carbonizados fazem\nmetade do trabalho. O que poucos sabem é que um desastre semelhante está ocorrendo nos oceanos. Ao longo\nde toda a costa, acompanhando as grandes ocupações\nhumanas, estão pipocando zonas mortas, áreas onde a\nbiodiversidade dos mares praticamente desaparece. Apesar de essas regiões não serem fotogênicas, elas vêm\ncrescendo de maneira assustadora.\nHoje há mais de quatrocentos locais onde praticamente\nnão existe mais vida oceânica. No total, estima-se que 245\nmil quilômetros quadrados estejam morrendo, o que equivale\na aproximadamente 5% da área coberta pela floresta amazônica. A causa desse fenômeno é a queda na quantidade\nde oxigênio dissolvido na água. Sem oxigênio, os peixes e\noutros animais desaparecem.\nA diminuição da quantidade de oxigênio é desencadeada pelo aumento na quantidade de nutrientes nas\nregiões costeiras. Essa abundância provoca um aumento rápido dos organismos que utilizam nutrientes, luz e\ngás carbônico. Num primeiro momento, esse crescimento\nno número de organismos capazes de fazer fotossíntese atrai outros animais, mas logo a água se turva com o\nexcesso de algas e bactérias e, sem luz, eles morrem.\nOs cadáveres se acumulam no fundo do mar e permitem\na multiplicação de organismos que consomem oxigênio\npara degradar a matéria orgânica acumulada. Nessa\nfase, o oxigênio diminui e desaparecem os peixes e outros animais maiores. Na falta de oxigênio, só sobrevivem\nos organismos anaeróbicos (que crescem na ausência de\noxigênio), os quais produzem uma quantidade crescente\nde compostos de enxofre, o que acaba por tornar o ambiente inóspito para a maioria dos animais.\nEmbora escapem aos olhos e com isso não sejam sentidas\npelo coração de cada um de nós, as zonas mortas não são menos importantes que o desmatamento da floresta amazônica.\nNa realidade, esse é mais um problema a ser enfrentado à medida que nos preparamos para dobrar a produção de alimentos.\nÉ bom lembrar que nos próximos cinquenta anos o número de\nbocas a ser alimentadas no planeta vai dobrar. Como sustentar\nessas pessoas preservando a Amazônia e os oceanos é um\ndos desafios tecnológicos a ser enfrentado por uma nova geração de agrônomos e ecólogos.\n(Fernando Reinach. A longa marcha dos grilos canibais e outras crônicas\nsobre a vida no planeta Terra, 2010. Adaptado.)", "support_image": null, "options": ["linguagem mais informal, como se pode observar em “A causa desse fenômeno é a queda na quantidade de oxigênio dissolvido na água.” (2o parágrafo)", "linguagem pessoal, como se pode observar em “A diminuição da quantidade de oxigênio é desencadeada pelo aumento na quantidade de nutrientes nas regiões costeiras.” (3o parágrafo)", "linguagem impessoal, como se pode observar em “Embora escapem aos olhos e com isso não sejam sentidas pelo coração de cada um de nós, as zonas mortas não são menos importantes que o desmatamento da floresta amazônica.” (4o parágrafo)", "linguagem mais coloquial, como se pode observar em “Ao longo de toda a costa, acompanhando as grandes ocupações humanas, estão pipocando zonas mortas, áreas onde a biodiversidade dos mares praticamente desaparece.” (1o parágrafo)", "linguagem técnica, como se pode observar em “Na falta de oxigênio, só sobrevivem os organismos anaeróbicos (que crescem na ausência de oxigênio), os quais produzem uma quantidade crescente de compostos de enxofre, o que acaba por tornar o ambiente inóspito para a maioria dos animais.” (3o parágrafo)"], "answer": "D", "explanation": null, "page": 7}, {"number": 17, "subject": "Língua Portuguesa", "text": "De acordo com o Dicionário eletrônico Houaiss da língua\nportuguesa, os dêiticos são termos linguísticos que se\nreferem “à situação em que o enunciado é produzido, ao\nmomento da enunciação e aos atores do discurso”. Por\nexemplo, “eu” designa a pessoa que fala “eu”. Termos\ncomo “aqui” e “agora” devem ser interpretados em função\nde onde e em que momento se encontra o locutor, quando\ndiz “aqui” ou “agora”.\nVerifica-se um dêitico que se refere ao momento em que o\nenunciado é produzido no seguinte trecho:", "support": "Leia o texto “Zonas mortas nos oceanos”, do biólogo brasileiro\nFernando Reinach, para responder às questões de 16 a 20.\nÉ fácil sensibilizar o mundo para o desmatamento da\nfloresta amazônica, fotos de troncos carbonizados fazem\nmetade do trabalho. O que poucos sabem é que um desastre semelhante está ocorrendo nos oceanos. Ao longo\nde toda a costa, acompanhando as grandes ocupações\nhumanas, estão pipocando zonas mortas, áreas onde a\nbiodiversidade dos mares praticamente desaparece. Apesar de essas regiões não serem fotogênicas, elas vêm\ncrescendo de maneira assustadora.\nHoje há mais de quatrocentos locais onde praticamente\nnão existe mais vida oceânica. No total, estima-se que 245\nmil quilômetros quadrados estejam morrendo, o que equivale\na aproximadamente 5% da área coberta pela floresta amazônica. A causa desse fenômeno é a queda na quantidade\nde oxigênio dissolvido na água. Sem oxigênio, os peixes e\noutros animais desaparecem.\nA diminuição da quantidade de oxigênio é desencadeada pelo aumento na quantidade de nutrientes nas\nregiões costeiras. Essa abundância provoca um aumento rápido dos organismos que utilizam nutrientes, luz e\ngás carbônico. Num primeiro momento, esse crescimento\nno número de organismos capazes de fazer fotossíntese atrai outros animais, mas logo a água se turva com o\nexcesso de algas e bactérias e, sem luz, eles morrem.\nOs cadáveres se acumulam no fundo do mar e permitem\na multiplicação de organismos que consomem oxigênio\npara degradar a matéria orgânica acumulada. Nessa\nfase, o oxigênio diminui e desaparecem os peixes e outros animais maiores. Na falta de oxigênio, só sobrevivem\nos organismos anaeróbicos (que crescem na ausência de\noxigênio), os quais produzem uma quantidade crescente\nde compostos de enxofre, o que acaba por tornar o ambiente inóspito para a maioria dos animais.\nEmbora escapem aos olhos e com isso não sejam sentidas\npelo coração de cada um de nós, as zonas mortas não são menos importantes que o desmatamento da floresta amazônica.\nNa realidade, esse é mais um problema a ser enfrentado à medida que nos preparamos para dobrar a produção de alimentos.\nÉ bom lembrar que nos próximos cinquenta anos o número de\nbocas a ser alimentadas no planeta vai dobrar. Como sustentar\nessas pessoas preservando a Amazônia e os oceanos é um\ndos desafios tecnológicos a ser enfrentado por uma nova geração de agrônomos e ecólogos.\n(Fernando Reinach. A longa marcha dos grilos canibais e outras crônicas\nsobre a vida no planeta Terra, 2010. Adaptado.)", "support_image": null, "options": ["“Hoje há mais de quatrocentos locais onde praticamente não existe mais vida oceânica.” (2o parágrafo)", "“A diminuição da quantidade de oxigênio é desencadeada pelo aumento na quantidade de nutrientes nas regiões costeiras.” (3o parágrafo)", "“É fácil sensibilizar o mundo para o desmatamento da floresta amazônica, fotos de troncos carbonizados fazem metade do trabalho.” (1o parágrafo)", "“Essa abundância provoca um aumento rápido dos organismos que utilizam nutrientes, luz e gás carbônico.” (3o parágrafo)", "“Nessa fase, o oxigênio diminui e desaparecem os peixes e outros animais maiores.” (3o parágrafo)"], "answer": "A", "explanation": null, "page": 8}, {"number": 18, "subject": "Língua Portuguesa", "text": "O autor inclui-se explicitamente no próprio texto no seguinte\ntrecho:", "support": "Leia o texto “Zonas mortas nos oceanos”, do biólogo brasileiro\nFernando Reinach, para responder às questões de 16 a 20.\nÉ fácil sensibilizar o mundo para o desmatamento da\nfloresta amazônica, fotos de troncos carbonizados fazem\nmetade do trabalho. O que poucos sabem é que um desastre semelhante está ocorrendo nos oceanos. Ao longo\nde toda a costa, acompanhando as grandes ocupações\nhumanas, estão pipocando zonas mortas, áreas onde a\nbiodiversidade dos mares praticamente desaparece. Apesar de essas regiões não serem fotogênicas, elas vêm\ncrescendo de maneira assustadora.\nHoje há mais de quatrocentos locais onde praticamente\nnão existe mais vida oceânica. No total, estima-se que 245\nmil quilômetros quadrados estejam morrendo, o que equivale\na aproximadamente 5% da área coberta pela floresta amazônica. A causa desse fenômeno é a queda na quantidade\nde oxigênio dissolvido na água. Sem oxigênio, os peixes e\noutros animais desaparecem.\nA diminuição da quantidade de oxigênio é desencadeada pelo aumento na quantidade de nutrientes nas\nregiões costeiras. Essa abundância provoca um aumento rápido dos organismos que utilizam nutrientes, luz e\ngás carbônico. Num primeiro momento, esse crescimento\nno número de organismos capazes de fazer fotossíntese atrai outros animais, mas logo a água se turva com o\nexcesso de algas e bactérias e, sem luz, eles morrem.\nOs cadáveres se acumulam no fundo do mar e permitem\na multiplicação de organismos que consomem oxigênio\npara degradar a matéria orgânica acumulada. Nessa\nfase, o oxigênio diminui e desaparecem os peixes e outros animais maiores. Na falta de oxigênio, só sobrevivem\nos organismos anaeróbicos (que crescem na ausência de\noxigênio), os quais produzem uma quantidade crescente\nde compostos de enxofre, o que acaba por tornar o ambiente inóspito para a maioria dos animais.\nEmbora escapem aos olhos e com isso não sejam sentidas\npelo coração de cada um de nós, as zonas mortas não são menos importantes que o desmatamento da floresta amazônica.\nNa realidade, esse é mais um problema a ser enfrentado à medida que nos preparamos para dobrar a produção de alimentos.\nÉ bom lembrar que nos próximos cinquenta anos o número de\nbocas a ser alimentadas no planeta vai dobrar. Como sustentar\nessas pessoas preservando a Amazônia e os oceanos é um\ndos desafios tecnológicos a ser enfrentado por uma nova geração de agrônomos e ecólogos.\n(Fernando Reinach. A longa marcha dos grilos canibais e outras crônicas\nsobre a vida no planeta Terra, 2010. Adaptado.)", "support_image": null, "options": ["“Essa abundância provoca um aumento rápido dos organismos que utilizam nutrientes, luz e gás carbônico.” (3o parágrafo)", "“O que poucos sabem é que um desastre semelhante está ocorrendo nos oceanos.” (1o parágrafo)", "“Na realidade, esse é mais um problema a ser enfrentado à medida que nos preparamos para dobrar a produção de alimentos.” (4o parágrafo)", "“É fácil sensibilizar o mundo para o desmatamento da floresta amazônica, fotos de troncos carbonizados fazem metade do trabalho.” (1o parágrafo)", "“Como sustentar essas pessoas preservando a Amazônia e os oceanos é um dos desafios tecnológicos a ser enfrentado por uma nova geração de agrônomos e ecólogos.” (4o parágrafo)"], "answer": "C", "explanation": null, "page": 8}, {